python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-terminate/TerminateParallel.bpmn')
root = tree.getroot()

ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
}

# Collect all ids
all_ids = {el.get('id') for el in root.iter() if el.get('id')}

# Collect flow nodes
proc = root.find('bpmn:process', ns)
flow_nodes = [el for el in proc if el.get('id')]
flow_node_ids = {el.get('id') for el in flow_nodes}

# Sequence flows
seq_flows = proc.findall('bpmn:sequenceFlow', ns)
seq_flow_ids = {f.get('id') for f in seq_flows}

# Check all refs resolve
errors = []
for sf in seq_flows:
    for attr in ('sourceRef', 'targetRef'):
        ref = sf.get(attr)
        if ref not in all_ids:
            errors.append(f'sequenceFlow {sf.get(\"id\")} {attr}={ref} not found')

# Check no activity/event has >1 incoming
for el in flow_nodes:
    incoming = el.findall('bpmn:incoming', ns)
    if len(incoming) > 1:
        errors.append(f'{el.tag} {el.get(\"id\")} has multiple incoming flows (FAKE_JOIN)')

# Check parallel gateway: no conditions on outgoing flows
for gw in proc.findall('bpmn:parallelGateway', ns):
    for out_id in [o.text for o in gw.findall('bpmn:outgoing', ns)]:
        for sf in seq_flows:
            if sf.get('id') == out_id:
                cond = sf.find('{http://www.omg.org/spec/BPMN/20100524/MODEL}conditionExpression')
                if cond is not None:
                    errors.append(f'Parallel gateway outgoing flow {out_id} has a condition (invalid)')

# Check parallel gateway: >=2 outgoing (fork) — at least 2
for gw in proc.findall('bpmn:parallelGateway', ns):
    out_count = len(gw.findall('bpmn:outgoing', ns))
    in_count  = len(gw.findall('bpmn:incoming', ns))
    if in_count == 1 and out_count < 2:
        errors.append(f'Parallel fork gateway {gw.get(\"id\")} has <2 outgoing flows')

# Check terminate end event definition
term_ends = [e for e in proc.findall('bpmn:endEvent', ns)
             if e.find('{http://www.omg.org/spec/BPMN/20100524/MODEL}terminateEventDefinition') is not None]
if not term_ends:
    errors.append('No terminate end event found')
else:
    print(f'Terminate end events: {[e.get(\"id\") for e in term_ends]}')

# Check BPMNDiagram shapes cover all flow node ids
diagram = root.find('bpmndi:BPMNDiagram', ns)
plane = diagram.find('bpmndi:BPMNPlane', ns)
shape_refs = {s.get('{http://www.omg.org/spec/BPMN/20100524/DI}bpmnElement') or
              s.get('bpmnElement')
              for s in plane.findall('bpmndi:BPMNShape', ns)}
# fix: bpmnElement is not namespaced
shape_refs2 = set()
for s in plane.findall('{http://www.omg.org/spec/BPMN/20100524/DI}BPMNShape', ns):
    pass
# use plain find
for s in plane:
    be = s.get('bpmnElement')
    if be:
        shape_refs2.add(be)
missing_shapes = flow_node_ids - shape_refs2
if missing_shapes:
    errors.append(f'Nodes missing BPMNShape: {missing_shapes}')

edge_refs = set()
for e in plane:
    be = e.get('bpmnElement')
    if be and be in seq_flow_ids:
        edge_refs.add(be)
missing_edges = seq_flow_ids - edge_refs
if missing_edges:
    errors.append(f'Flows missing BPMNEdge: {missing_edges}')

if errors:
    for e in errors:
        print('ERROR:', e)
else:
    print('VALID - all structural checks passed')
"

